begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values ('77777777-7777-4777-8777-777777777777','prefs-alice@example.test'),('88888888-8888-4888-8888-888888888888','prefs-bob@example.test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"77777777-7777-4777-8777-777777777777","role":"authenticated"}',true);
select set_config('test.prefs',public.create_idea_project('{"title":"Preferences","targetDurationMs":30000,"audienceLevel":"advanced","tone":"conversational","settings":{"voice":"male"}}','prefs-create-key-0001')::text,true);
select is(current_setting('test.prefs')::jsonb->'settings','{"voice":"male","captions":true,"theme":"topic"}'::jsonb,'Partial create settings merge required defaults');
select is(current_setting('test.prefs')::jsonb->>'targetDurationMs','30000','Duration selected');
select is(current_setting('test.prefs')::jsonb->>'audienceLevel','advanced','Audience selected');
select is(current_setting('test.prefs')::jsonb->>'tone','conversational','Tone selected');
select is(public.create_idea_project('{"title":"Preferences","targetDurationMs":30000,"audienceLevel":"advanced","tone":"conversational","settings":{"voice":"male"}}','prefs-create-key-0001'),current_setting('test.prefs')::jsonb,'Preference create replay exact');
select throws_ok(format('select public.create_idea_project(%L::jsonb,%L)',jsonb_build_object('settings',s)::text,'prefs-invalid-key-001'),'P0001','VALIDATION_FAILED','Unsupported settings rejected: '||s::text)
 from (values ('null'::jsonb),('[]'::jsonb),('{"voice":"neutral"}'::jsonb),('{"voiceId":"paid-id"}'::jsonb),('{"captions":false}'::jsonb),('{"captions":"true"}'::jsonb),('{"theme":"fixed"}'::jsonb),('{"voice":null}'::jsonb),('{"theme":null}'::jsonb),('{"captions":null}'::jsonb)) cases(s);
select set_config('test.prefs2',public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":1,"settings":{"voice":"female"}}','prefs-save-key-00001')::text,true);
select is(current_setting('test.prefs2')::jsonb->'settings','{"voice":"female","captions":true,"theme":"topic"}'::jsonb,'Settings-only PATCH creates new snapshot');
select is(current_setting('test.prefs2')::jsonb->>'targetDurationMs','30000','Settings-only PATCH retains other preferences');
select set_config('test.prefs3',public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":2,"brief":"Text change"}','prefs-save-key-00002')::text,true);
select is(current_setting('test.prefs3')::jsonb->'settings'->>'voice','female','Text-only save retains chosen voice');
select set_config('test.prefs4',public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":3,"settings":{"voice":"male"}}','prefs-save-key-00003')::text,true);
select set_config('test.prefs5',public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":4,"settings":{}}','prefs-save-key-00004')::text,true);
select is(current_setting('test.prefs5')::jsonb->'settings'->>'voice','male','Empty settings patch does not reset saved voice');
select is((select settings->>'voice' from public.project_revisions where project_id=(current_setting('test.prefs')::jsonb->>'id')::uuid and revision=2),'female','Historical voice preserved');
select isnt((select content_hash from public.project_revisions where project_id=(current_setting('test.prefs')::jsonb->>'id')::uuid and revision=3),(select content_hash from public.project_revisions where project_id=(current_setting('test.prefs')::jsonb->>'id')::uuid and revision=4),'Voice-only change affects creative hash');
select set_config('test.prefs6',public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":5,"targetDurationMs":90000,"audienceLevel":"beginner","tone":"clear"}','prefs-save-key-00005')::text,true);
select is(current_setting('test.prefs6')::jsonb->'settings'->>'voice','male','Duration/audience/tone save retains voice');
select set_config('test.prefscopy',public.duplicate_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":6}','prefs-copy-key-00001')::text,true);
select is(current_setting('test.prefscopy')::jsonb->'settings',current_setting('test.prefs6')::jsonb->'settings','Duplicate retains preferences');
select set_config('test.prefstrash',public.trash_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":6}','prefs-trash-key-0001')::text,true);
select set_config('test.prefsrestored',public.restore_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":7}','prefs-restore-key-01')::text,true);
select is(current_setting('test.prefsrestored')::jsonb->'settings',current_setting('test.prefs6')::jsonb->'settings','Trash/restore retain preferences');
select is(current_setting('test.prefsrestored')::jsonb->>'targetDurationMs','90000','Restoration retains selected duration');
select throws_ok($$select public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":6,"settings":{"voice":"female"}}','prefs-stale-key-0001')$$,'P0001','REVISION_CONFLICT','Old preference save is fenced');
select set_config('test.legacy',public.create_idea_project('{"title":"Legacy"}','prefs-legacy-create1')::text,true);
reset role;
select is((select request_hash from private.project_commands where owner_id='77777777-7777-4777-8777-777777777777' and operation='create' and command_key='prefs-legacy-create1'),encode(extensions.digest('{"title":"Legacy","brief":"","referenceText":"","targetDurationMs":60000,"audienceLevel":"beginner","tone":"clear"}'::jsonb::text,'sha256'),'hex'),'No-settings create keeps pre-migration request hash');
set local role authenticated;
select is(public.create_idea_project('{"title":"Legacy"}','prefs-legacy-create1'),current_setting('test.legacy')::jsonb,'Legacy create retry supported');
select set_config('test.legacy2',public.save_idea_project((current_setting('test.legacy')::jsonb->>'id')::uuid,'{"expectedRevision":1,"title":"Legacy","brief":"Legacy save","referenceText":""}','prefs-legacy-save01')::text,true);
select set_config('test.legacy3',public.save_idea_project((current_setting('test.legacy')::jsonb->>'id')::uuid,'{"expectedRevision":2,"settings":{"voice":"male"}}','prefs-legacy-save02')::text,true);
select is(public.save_idea_project((current_setting('test.legacy')::jsonb->>'id')::uuid,'{"expectedRevision":1,"title":"Legacy","brief":"Legacy save","referenceText":""}','prefs-legacy-save01'),current_setting('test.legacy2')::jsonb,'Legacy text request replays original acknowledgement after preference changes');
select is(public.get_idea_project((current_setting('test.legacy')::jsonb->>'id')::uuid)->'settings'->>'voice','male','Legacy replay does not reset newer saved voice');
select set_config('request.jwt.claims','{"sub":"88888888-8888-4888-8888-888888888888","role":"authenticated"}',true);
select throws_ok($$select public.save_idea_project((current_setting('test.prefs')::jsonb->>'id')::uuid,'{"expectedRevision":8,"settings":{"voice":"female"}}','prefs-foreign-key01')$$,'P0001','RESOURCE_NOT_FOUND','Foreign preferences inaccessible');
select * from finish();
rollback;
